let route='feed', post=0, asset=0, lens='Pentru tine', paused=false, muted=true, reaction='', saved=false, reposted=false, followed=false;
let profileTab='Postări', relationTab='Urmărești', searchTab='Tot', recipients=new Set(), replyTo='', ownComments=[], messages=[], selectedPerson='Mira', toastTimer, progressTimer, storyTimer, progress=38, storyProgress=0;
let draftCaption='', displayName='Romeo', bio='Oameni, locuri și lucruri care merită păstrate.', options={private:false,activity:true,messages:true};
const root=document.getElementById('prototype');
const titles=Object.fromEntries(catalogue.map(s=>[s[0],s[2]]));
function top(title,back='back',right='search') {return `<header class="topbar">${button(back,'back','Înapoi')}<h2>${esc(title)}</h2>${right?go(right,right==='settings'?'settings':right==='meeting'?'more':'search',right==='settings'?'Setări':'Caută'):''}</header>`;}
function dock(active='feed'){return `<nav class="dock" aria-label="Navigare Nexus">${[['feed','home','Acasă'],['inbox','chat','Mesaje'],['create','plus','Creează'],['live','live','Live'],['profile','profile','Profil']].map(([id,s,l])=>go(id,s,l,id==='create'?'create':id===active?'selected':'',id==='create'?'':`<span>${l}</span>`)).join('')}</nav>`;}
function media(full=false,rail=true){const current=(post+asset)%3;return `<div class="media" data-gesture="media" data-post="${post}" data-asset="${asset}">${photo(current)}<div class="shade"></div>${full?`<div class="media-header">${button('back','close','Închide fullscreen')}<span class="pill">${esc(lens)}</span>${go('channels','settings','Filtre')}</div><div class="gesture-nav">${button('prev','back','Conținut anterior')}${button('next','next','Conținut următor')}</div>`:`<span class="media-count">${post+1} / 3</span>`}${asset?`<span class="photo-position">${asset+1} / 3</span>`:''}${rail?`<div class="media-content"><div class="identity">${go('creator','', 'Vezi creatorul','',avatar(['Mira','Alex','Ana'][post],post))}<b>${['Mira','Alex','Ana'][post]}</b>${button('follow','','Urmărește','follow',followed?'Urmărești':'Urmărește')}</div><p>${['O melodie, un apus. Atât. ✨','Mai aproape de liniște.','Ora aceea în care nu te grăbești.'][post]}</p><small>♫ Sunet original · ${['Mira','Alex','Ana'][post]}</small></div><aside class="rail" aria-label="Acțiuni conținut">${button('go:reactions',reaction?'':'heart','Alege reacția',reaction?'selected':'',`${reaction || ''}<small>${reaction?'249':'248'}</small>`)}${go('comments','chat','Comentarii','',`<small>${4+ownComments.length}</small>`)}${button('repost','repost','Redistribuie în Nexus',reposted?'selected':'','<small>12</small>')}${go('send','send','Trimite în Nexus')}${button('save','save','Salvează',saved?'selected':'')}${button('mute',muted?'mute':'sound',muted?'Pornește sunetul':'Oprește sunetul')}</aside>`:''}${paused?`<div class="pause-state">${icon('play')}</div>`:''}</div>`;}
function storyRow(){return `<div class="stories">${go('camera','','Story nou','story',`${avatar('+',0,'new')}<span>Story nou</span>`)}${['Mira','Alex','Ana','Luca'].map((n,i)=>go('stories','',`Story ${n}`,'story',`${avatar(n,i)}<span>${n}</span>`)).join('')}</div>`;}
function feed(){return `<div class="screen"><header class="topbar">${button('home','','Nexus Acasă','logo','NE<em>✕</em>US')}${go('channels','down','Alege feedul','pill',esc(lens))}${go('relations','people','Oamenii tăi')}${go('search','search','Caută în Nexus')}</header>${post===0?storyRow():''}${media()}${dock()}</div>`;}
function sheet(title,content,base='fullscreen',cls=''){return `${base==='chat'?chat():base==='profile'?profile():base==='feed'?feed():`<div class="screen">${media(true,false)}</div>`}<button class="scrim" data-action="back" aria-label="Închide panoul"></button><section class="sheet ${cls}" role="dialog" aria-modal="true" aria-label="${esc(title)}"><div class="handle" data-gesture="dismiss"></div><header class="sheet-head"><h2>${esc(title)}</h2>${button('back','close','Închide panoul')}</header>${content}</section>`;}
function comment(name,text,reply=false){return `<article class="comment ${reply?'reply':''}">${avatar(name,reply?2:1)}<div><b>${esc(name)}</b><small>2 min</small><p>${esc(text)}</p><div class="comment-actions">${button(`reply:${name}`,'','Răspunde lui '+name,'','Răspunde')}${button('comment-like','','Apreciază comentariul','','♡ 12')}</div></div></article>`;}
function comments(){return sheet('Comentarii',`<div class="body">${comment('Alex','Sunetul și locul. Combinația perfectă.')}${comment('Mira','Exact asta am simțit și eu.',true)}${comment('Ana','Unde este filmat?')}${comment('Luca','Mai vrem astfel de seri.')}${ownComments.map(c=>comment('Tu',c.text,!!c.parent)).join('')}</div>${replyTo?`<div class="reply-label">Răspunzi lui ${esc(replyTo)} ${button('cancel-reply','close','Anulează răspunsul')}</div>`:''}<form class="compose" data-form="comment"><input name="message" aria-label="Comentariu" placeholder="Adaugă un comentariu…" maxlength="2000" required><button class="ib send" aria-label="Trimite comentariul">${icon('send')}</button></form>`,'fullscreen','comments');}
function rows(action='chat',query=''){return people.filter(p=>p.join(' ').toLowerCase().includes(query.toLowerCase())).map(([name,last,time],i)=>`<button class="row" data-action="${action}:${name}">${avatar(name,i)}<span><b>${name}</b><small>${last}</small></span><time>${time}${i<2?'<i class="unread"></i>':''}</time></button>`).join('');}
function searchField(label='Caută',id='search'){return `<label class="search-field">${icon('search')}<input aria-label="${label}" placeholder="${label}" data-search="${id}"></label>`;}
function inbox(){return `<div class="screen">${top('Mesaje','home','meeting')}<div class="body padded">${searchField('Caută în mesaje','inbox')}<div class="chips">${button('inbox-filter:all','','Toate','selected','Toate')}${button('inbox-filter:unread','','Necitite','','Necitite · 2')}${go('meeting','','Grupuri','','Grupuri')}</div><div class="section-title"><h3>Conversații</h3>${go('requests','','Cereri de mesaje','','Cereri · 1')}</div><div data-results>${rows()}</div></div>${dock('inbox')}</div>`;}
function chat(){return `<div class="screen"><header class="topbar">${go('inbox','back','Înapoi la mesaje')}${avatar(selectedPerson)}<h2>${esc(selectedPerson)}</h2>${go('call','video','Apel video')}${go('meeting','more','Detalii conversație')}</header><div class="body chat-body"><div class="date">Astăzi · conversație demonstrativă</div><div class="bubble">Am găsit un loc pentru weekend.<small>18:24</small></div><div class="bubble mine">Perfect. Trimite-mi o fotografie!<small>18:25 ✓✓</small></div><div class="bubble">${photo()}<span>Aici. Ce zici?</span><small>18:26</small></div><div class="bubble mine"><blockquote>${esc(selectedPerson)} · Aici. Ce zici?</blockquote>Da! Ne vedem sâmbătă 🌿<small>18:27 ✓✓</small></div>${messages.map(m=>`<div class="bubble mine">${esc(m)}<small>acum · demo ✓</small></div>`).join('')}</div><form class="compose chat-compose" data-form="chat">${go('attachments','plus','Adaugă atașament')}<input name="message" placeholder="Mesaj…" aria-label="Mesaj" required maxlength="4000">${button('voice','mic','Notă vocală')}<button class="ib send" aria-label="Trimite mesajul">${icon('send')}</button></form></div>`;}
function grid(){return `<div class="grid">${Array.from({length:9},(_,i)=>button(`open:${i%3}`,'',`Deschide postarea ${i+1}`,'tile',`${photo(i)}${icon(i%3===0?'play':'image')}`)).join('')}</div>`;}
function profile(other=false){return `<div class="screen">${top(other?'@mira':'@romeo','home',other?'search':'settings')}<div class="body"><div class="profile-cover"></div><section class="profile-info">${avatar(other?'Mira':displayName)}<h2>${other?'Mira Ionescu':esc(displayName)}</h2><small>${other?'Muzică • natură • seri liniștite':'@romeo · Social'}</small><p>${other?'Păstrez aici lucrurile care mă fac să mă opresc.':esc(bio)}</p><div class="stats">${[['104','postări'],['1.248','urmăritori'],['178','urmărești']].map(([n,l])=>go(l==='postări'?'profile':'relations','',l,'',`<b>${n}</b><small>${l}</small>`)).join('')}</div><div class="buttons">${other?button('follow','','Urmărește creatorul','primary',followed?'Urmărești':'Urmărește')+go('chat','','Mesaj','secondary','Mesaj'):go('edit','','Editează profilul','secondary','Editează profilul')+go('wallet','wallet','Portofel','secondary','Portofel')}</div></section><div class="tabs" role="tablist" aria-label="Conținut profil">${['Postări','Clips','Colecții','Despre'].map(t=>`<button role="tab" aria-selected="${profileTab===t}" class="${profileTab===t?'selected':''}" data-action="profile-tab:${t}">${t}</button>`).join('')}</div>${profileTab==='Despre'?'<div class="padded"><h3>Lucrurile care mă reprezintă</h3><p class="quiet">Muzică · drumeții · fotografie</p><div class="card"><b>Social</b><p>Informațiile tale publice apar aici. Datele contului sunt în Setări.</p></div></div>':profileTab==='Colecții'?collectionBody():grid()}</div>${dock('profile')}</div>`;}
function collectionBody(){return `<div class="padded"><div class="section-title"><h3>Colecții private</h3>${button('new-collection','plus','Colecție nouă')}</div><div class="choices">${['Locuri','Inspirație','Muzică','Mai târziu'].map((n,i)=>go('fullscreen','folder',n,'',n)).join('')}</div></div>`;}
function option(action,symbol,title,description='',tail='next'){return `<button class="option" data-action="${action}">${icon(symbol)}<span><b>${title}</b>${description?`<small>${description}</small>`:''}</span>${tail?icon(tail):''}</button>`;}
function renderScreen(id){switch(id){
case 'feed':return feed();
case 'fullscreen':return `<div class="screen">${media(true)}</div>`;
case 'comments':return comments();
case 'reactions':return sheet('Cum ți se pare?',`<div class="reactions">${[['♡','Like'],['❤️','Love'],['😂','Haha'],['😮','Wow'],['😢','Sad'],['😡','Angry'],['◇','Fake?'],['↓','Dislike']].map(([e,n])=>button(`react:${e}`,'',n,'',`${e}<small>${n}</small>`)).join('')}</div><p class="quiet">Reacțiile exprimă opinii. Dislike este privat.</p>`);
case 'send':return sheet('Trimite în Nexus',`${searchField('Caută o persoană','send')}<div class="body" data-results>${people.map(([n],i)=>`<button class="row" data-action="recipient:${n}">${avatar(n,i)}<span><b>${n}</b><small>${i===2?'Grup':'Conversație'}</small></span>${recipients.has(n)?icon('check'):icon('plus')}</button>`).join('')}</div>${button('send-internal','send','Trimite selecției','primary',`Trimite${recipients.size?' · '+recipients.size:''}`)}`);
case 'channels':return sheet('Feedul tău',`<div class="body">${[['Pentru tine','star','După interesele tale'],['Local','pin','România · Schimbă din Setări'],['Global','globe','Din întreaga lume'],['Urmărești','people','Oamenii aleși de tine']].map(([n,s,d])=>option('lens:'+n,s,n,d,lens===n?'check':'next')).join('')}<div class="section-title"><h3>Format</h3></div><div class="chips">${['Mix','Clips','Fotografii','Text'].map(n=>button('format:'+n,'',n,'',n)).join('')}</div>${option('go:settings','settings','Preferințe feed')}</div>`,'feed');
case 'relations':return `<div class="screen">${top('Oamenii tăi','home','')}<div class="body padded">${searchField('Caută o persoană','relations')}<div class="chips">${['Urmăritori','Urmărești','Favoriți'].map(t=>button('relation-tab:'+t,'',t,relationTab===t?'selected':'',t)).join('')}</div><div data-results>${people.map(([n],i)=>`<div class="row">${go('creator','',`Profil ${n}`,'',avatar(n,i))}<span><b>${n}</b><small>@${n.toLowerCase().replaceAll(' ','_')}</small></span>${button('favorite:'+n,'star','Favorit '+n)}${button('chat:'+n,'chat','Mesaj '+n)}</div>`).join('')}</div></div>${dock()}</div>`;
case 'stories':return `<div class="screen"><div class="media">${photo(post)}<div class="shade"></div><div class="story-progress"><i></i><i></i><i></i></div><div class="media-header story-person"><div class="identity">${avatar('Mira')}<b>Mira</b><small>2 h</small></div>${button('story-pause',paused?'play':'clock',paused?'Reia story':'Pauză story')}${button('back','close','Închide story')}</div><div class="story-taps" data-gesture="story">${button('story-prev','','Story anterior')}${button('story-next','','Story următor')}</div><form class="story-response" data-form="story"><input name="message" aria-label="Răspunde la story" placeholder="Răspunde…" required>${button('story-like','heart','Apreciază story')}<button class="ib" aria-label="Trimite răspunsul">${icon('send')}</button></form></div></div>`;
case 'search':return `<div class="screen">${top('Caută','home','')}<div class="body padded">${searchField('Oameni, clipuri, orice…','global')}<div class="chips">${['Tot','Oameni','Clips','Foto','Text','Sunete'].map(t=>button('search-tab:'+t,'',t,searchTab===t?'selected':'',t)).join('')}</div><div data-results>${rows('creator')}${grid()}</div></div>${dock()}</div>`;
case 'inbox':return inbox();
case 'requests':return `<div class="screen">${top('Cereri','go:inbox','')}<div class="body padded"><div class="row">${avatar('Irina',1)}<span><b>Irina</b><small>Bună! Am văzut clipul tău.</small></span></div><div class="buttons">${button('accept','','Acceptă cererea','primary','Acceptă')}${button('decline','','Refuză cererea','secondary','Refuză')}</div>${option('block','flag','Blochează sau raportează')}</div></div>`;
case 'chat':return chat();
case 'attachments':return sheet('Adaugă',`<div class="choices">${go('camera','camera','Cameră','','Cameră')}${go('editor','image','Galerie','','Galerie')}${button('attach-file','folder','Fișier','','Fișier')}${button('voice','mic','Audio','','Audio')}</div>`,'chat');
case 'call':return `<div class="screen">${top('Apel · previzualizare','go:chat','')}<div class="call-face">${avatar(selectedPerson)}<h2>${esc(selectedPerson)}</h2><p class="quiet">Machetă de apel video</p></div><div class="call-actions">${button('call-toggle:mic','mic','Microfon')}${button('call-toggle:camera','video','Cameră')}${button('call-toggle:sound','sound','Difuzor')}${go('chat','phone','Încheie apelul','ib danger')}</div></div>`;
case 'meeting':return `<div class="screen">${top('Întâlnire','go:chat','')}<div class="body padded"><form data-form="meeting"><label class="field">Titlu<input name="title" placeholder="O idee de discutat" required></label><label class="field">Data<input name="date" type="date" required></label><label class="field">Ora<input name="time" type="time" required></label>${option('go:relations','people','Participanți','Alege dintre oamenii tăi')}<button class="primary" type="submit">Adaugă în conversație</button></form></div></div>`;
case 'profile':return profile();case 'creator':return profile(true);
case 'edit':return `<div class="screen">${top('Editează profilul','go:profile','')}<div class="body padded"><form data-form="profile"><div class="identity">${avatar(displayName)}${go('editor','image','Schimbă fotografia','secondary','Schimbă fotografia')}</div><label class="field">Nume<input name="name" value="${esc(displayName)}" maxlength="60" required></label><label class="field">Username<input name="username" value="romeo" maxlength="24" required pattern="[a-zA-Z0-9_]{3,24}"></label><label class="field">Bio<textarea name="bio" maxlength="160">${esc(bio)}</textarea></label><label class="field">Regiune<select><option>România</option><option>Polonia</option><option>Global</option></select></label><button class="primary">Salvează</button></form></div></div>`;
case 'collections':return `<div class="screen">${top('Colecții','go:profile','')}${collectionBody()}${dock('profile')}</div>`;
case 'wallet':return `<div class="screen">${top('Portofel','go:profile','')}<div class="body padded"><span class="quiet">PORTOFEL DEMONSTRATIV</span><div class="hero-number">$128<span class="quiet">.40</span></div><p class="quiet">Active fictive pentru proiectul vizual</p><div class="buttons" style="margin-top:20px">${button('pay-preview:Încarcă','plus','Încarcă','primary','Încarcă')}${button('pay-preview:Trimite','send','Trimite','secondary','Trimite')}</div><div class="section-title"><h3>Active</h3>${icon('wallet')}</div><div class="row">${avatar('US',2)}<span><b>USDC</b><small>Stablecoin · demonstrativ</small></span><b>100.00</b></div><div class="row">${avatar('EG',0)}<span><b>EGLD</b><small>MultiversX · demonstrativ</small></span><b>1.24</b></div>${option('pay-preview:Adresă','wallet','Adresa mea MultiversX')}${option('pay-preview:Activitate','clock','Activitate')}${option('go:settings','lock','Securitate și recuperare')}</div></div>`;
case 'settings':return `<div class="screen">${top('Setări','go:profile','')}<div class="body padded">${searchField('Caută în setări','settings')}<div data-results>${option('go:edit','profile','Contul meu','Nume, username, bio')}${option('go:privacy','lock','Confidențialitate','Vizibilitate, mesaje, comentarii')}${option('theme','settings','Aspect','Închis / Deschis')}${option('region','globe','Limbă și regiune','Română · România')}${option('toggle:activity','chat','Notificări','Mesaje și activitate')}${option('go:collections','save','Conținut salvat')}${option('go:wallet','wallet','Portofel')}${option('help','flag','Ajutor și siguranță')}${option('go:login','back','Ieșire din prototip')}</div></div></div>`;
case 'privacy':return `<div class="screen">${top('Confidențialitate','go:settings','')}<div class="body padded"><span class="quiet">PROFIL SOCIAL</span>${[['private','lock','Profil privat'],['activity','clock','Arată activitatea'],['messages','chat','Permite cereri de mesaje']].map(([k,s,n])=>`<button class="option" role="switch" aria-checked="${options[k]}" data-action="toggle:${k}">${icon(s)}<span><b>${n}</b></span><i class="toggle ${options[k]?'on':''}"></i></button>`).join('')}${option('audience','people','Cine poate comenta','Urmăritori')}${option('blocked','flag','Conturi blocate')}${option('audience','profile','Mențiuni și etichetări','Persoanele pe care le urmărești')}</div></div>`;
case 'create':return sheet('Creează',`<div class="choices">${go('camera','camera','Deschide camera','','Cameră')}${go('editor','image','Alege din galerie','','Galerie')}</div>${option('go:publish','text','Scrie o postare')}${option('go:drafts','folder','Ciorne','2 în acest proiect')}${option('go:live','live','Pregătește un live')}`,'feed');
case 'camera':return `<div class="screen">${top('Cameră','go:create','')}<div class="capture-area"><div class="capture-center">${icon('camera')}<b>Previzualizare selfie</b><p class="quiet">Machetă de cameră.<br>Dispozitivul nu este pornit.</p></div></div><div class="chips" style="justify-content:center"><button data-action="camera-mode:Foto" class="selected">Foto</button><button data-action="camera-mode:Clip">Clip</button><button data-action="camera-mode:Story">Story</button></div><div class="capture-controls">${go('editor','image','Galerie')}${go('editor','camera','Capturează în prototip','shutter')}${button('camera-flip','refresh','Schimbă camera')}</div></div>`;
case 'editor':return `<div class="screen">${top('Editează','go:create','')}<div class="media">${photo()}<div class="shade"></div></div><div class="chips" style="padding:14px;justify-content:center">${button('edit-tool:Încadrare','grid','Încadrare','','Cadru')}${button('edit-tool:Text','text','Text','','Text')}${button('edit-tool:Sunet','sound','Sunet','','Sunet')}</div><div class="buttons padded">${button('save-draft','','Salvează ciorna','secondary','Ciornă')}${go('publish','','Înainte','primary','Înainte')}</div></div>`;
case 'publish':return `<div class="screen">${top('Postare nouă','go:editor','')}<div class="body padded"><form data-form="publish"><div class="chips">${['Postare','Clip','Story'].map((n,i)=>button('publish-type:'+n,'',n,i===0?'selected':'',n)).join('')}</div><textarea aria-label="Descriere" name="caption" placeholder="Ce vrei să spui?" maxlength="2000">${esc(draftCaption)}</textarea>${option('audience','globe','Public','Alege cine poate vedea')}${option('location','pin','Adaugă locație','Opțional')}${option('duration','clock','Durată Story','24 de ore · modificabil')}${option('go:editor','image','Editează media')}<button class="primary" type="submit" style="width:100%;margin-top:20px">Publică în prototip</button></form></div></div>`;
case 'progress':return `<div class="screen">${top('Se pregătește','home','')}<div class="empty"><div class="progress-ring" role="progressbar" aria-label="Progres simulat" aria-valuemin="0" aria-valuemax="100" aria-valuenow="${progress}">${progress}%</div><h2>Încărcare demonstrativă</h2><p>Poți reveni la feed. Materialul rămâne în ciorne.</p><div class="buttons">${button('upload-pause','','Pauză upload','secondary','Pauză')}${go('feed','','Continuă în feed','primary','Mergi la feed')}</div>${button('save-draft','','Anulează și păstrează ciorna','','Păstrează ciorna')}</div></div>`;
case 'drafts':return `<div class="screen">${top('Ciorne','go:create','')}<div class="body padded"><p class="quiet">Salvate local în proiectul vizual.</p><div class="choices">${go('editor','image','Ciornă fotografie','','Apus la munte')}${go('editor','video','Ciornă clip','','O idee nouă')}</div></div></div>`;
case 'live':return `<div class="screen">${top('Live','home','search')}<div class="body padded"><div class="chips"><button class="selected" data-action="live-filter:Acum">Acum</button><button data-action="live-filter:Urmărești">Urmărești</button></div><div class="tile" style="aspect-ratio:4/5">${photo()}<span class="photo-position">PREVIZUALIZARE</span></div><div class="section-title"><h3>Mira · Muzică la apus</h3></div><p class="quiet">Camere demonstrative. Transmisia reală nu este activă.</p>${go('camera','live','Pregătește un live','primary','Pregătește un live')}</div>${dock('live')}</div>`;
case 'login':return `<div class="screen"><div class="empty" style="align-items:stretch;text-align:left"><div class="logo" style="font-size:35px;letter-spacing:.16em">NE<em>✕</em>US</div><h2>Locul tău. Oamenii tăi.</h2>${button('login-demo','','Continuă cu Google','secondary','Continuă cu Google')}${button('login-demo','','Conectează xPortal','secondary','Conectează xPortal')}<form data-form="login"><label class="field">Email<input aria-label="Email" type="email" autocomplete="off"></label><label class="field">Parolă<input aria-label="Parolă" type="password" autocomplete="off"></label><button class="primary" style="width:100%">Intră în prototip</button></form>${button('recover','','Am uitat parola','','Am uitat parola')}${button('register','','Creează cont','','Creează cont')}<p class="quiet">Previzualizare. Nu introduce date reale.</p></div></div>`;
case 'empty':return `<div class="screen">${top('Mesaje','home','')}<div class="empty">${icon('chat')}<h2>Începe o conversație</h2><p>Găsește pe cineva după username.</p>${go('search','search','Caută o persoană','primary','Caută pe cineva')}</div>${dock('inbox')}</div>`;
case 'offline':return `<div class="screen">${top('Conexiune','home','')}<div class="empty">${icon('refresh')}<h2>Conexiunea s-a întrerupt</h2><p>Ciorna ta este aici. Reîncearcă atunci când revii online.</p>${button('retry','refresh','Reîncearcă','primary','Reîncearcă')}${go('drafts','','Vezi ciornele','secondary','Ciorne')}</div>${dock()}</div>`;
default:return feed();}}
function navigate(id,replace=false){if(!titles[id])return;const url=new URL(location.href);url.hash=id;const depth=Number(history.state?.nexusDesignDepth||0);if(replace)history.replaceState({nexusDesign:true,nexusDesignDepth:depth},'',url);else history.pushState({nexusDesign:true,nexusDesignDepth:depth+1},'',url);route=id;render();}
function back(){if(Number(history.state?.nexusDesignDepth)>0)history.back();else navigate(['chat','requests','attachments','call','meeting'].includes(route)?'inbox':'feed',true);}
function notify(text){clearTimeout(toastTimer);const t=document.getElementById('design-toast');t.textContent=text;t.hidden=false;toastTimer=setTimeout(()=>t.hidden=true,2600);}
function showDetail(title,content){root.insertAdjacentHTML('beforeend',`<button class="scrim detail" data-action="detail-close" aria-label="Închide"></button><section class="sheet detail" role="dialog" aria-modal="true" aria-label="${esc(title)}"><header class="sheet-head"><h2>${esc(title)}</h2>${button('detail-close','close','Închide')}</header>${content}</section>`);root.querySelector('.sheet.detail button')?.focus();}
function render(){clearInterval(storyTimer);if(route!=='progress')clearInterval(progressTimer);root.innerHTML=renderScreen(route);root.querySelectorAll('.scrim:not(.detail)').forEach(scrim=>{let sib=scrim.previousElementSibling;if(sib){sib.inert=true;sib.setAttribute('aria-hidden','true');}});document.getElementById('screen-number').textContent=`${String(catalogue.findIndex(s=>s[0]===route)+1).padStart(2,'0')} / ${catalogue.length}`;document.querySelectorAll('#screen-list a').forEach(a=>a.classList.toggle('active',a.hash==='#'+route));const s=catalogue.find(s=>s[0]===route);document.getElementById('screen-notes').innerHTML=`<span class="eyebrow">${esc(s[1]).toUpperCase()}</span><h2>${esc(s[2])}</h2><p>${esc(s[3])}</p><ol>${s[4].map(n=>`<li>${esc(n)}</li>`).join('')}</ol><div class="note-footer">Propunere UX · prototip independent<br>Acțiunile simulează rezultate locale. Integrarea în produs și verificarea vizuală sunt pași separați.</div>`;wireGestures();if(route==='progress'){progressTimer=setInterval(()=>{progress=Math.min(100,progress+7);const ring=root.querySelector('.progress-ring');if(!ring)return;ring.textContent=progress+'%';ring.setAttribute('aria-valuenow',progress);if(progress===100){clearInterval(progressTimer);navigate('profile',true);notify('Publication simulée · aucun upload réel');}},600);}if(route==='stories'){storyTimer=setInterval(()=>{if(paused||document.hidden)return;storyProgress+=2;root.style.setProperty('--progress',storyProgress+'%');if(storyProgress>=100){storyProgress=0;post=(post+1)%3;render();}},100);} }
function wireGestures(){root.querySelectorAll('[data-gesture]').forEach(el=>{let start=null,moved=false;el.addEventListener('pointerdown',e=>{if(e.target.closest('button,input,a,textarea')&&el.dataset.gesture!=='story')return;start={x:e.clientX,y:e.clientY};moved=false;el.setPointerCapture?.(e.pointerId);});el.addEventListener('pointerup',e=>{if(!start)return;let dx=e.clientX-start.x,dy=e.clientY-start.y;start=null;if(Math.max(Math.abs(dx),Math.abs(dy))<48)return;moved=true;if(el.dataset.gesture==='dismiss'){if(dy>48)back();return;}if(el.dataset.gesture==='story'){post=(post+(dx<0?1:2))%3;storyProgress=0;render();return;}if(route==='feed'&&post===0&&dy>80&&Math.abs(dy)>Math.abs(dx)){notify('Feed reîmprospătat · simulare locală');return;}if(Math.abs(dx)>Math.abs(dy))asset=(asset+(dx<0?1:2))%3;else{post=(post+(dy<0?1:2))%3;asset=0;}render();});el.addEventListener('pointercancel',()=>start=null);el.addEventListener('click',e=>{if(moved){moved=false;return;}if(e.target.closest('button,input,a,textarea'))return;if(el.dataset.gesture==='media'){if(route==='feed')navigate('fullscreen');else{paused=!paused;render();}}});el.addEventListener('wheel',e=>{if(el.dataset.gesture!=='media'||Math.abs(e.deltaY)<30)return;e.preventDefault();if(el.dataset.busy)return;el.dataset.busy='1';post=(post+(e.deltaY>0?1:2))%3;asset=0;render();},{passive:false});});}
document.addEventListener('click',e=>{const el=e.target.closest('[data-action]');if(!el||!root.contains(el))return;const [a,...parts]=el.dataset.action.split(':');const v=parts.join(':');if(a==='go')return navigate(v);if(a==='back')return back();if(a==='home'){post=0;asset=0;return navigate('feed');}if(a==='detail-close'){root.querySelectorAll('.detail').forEach(n=>n.remove());return;}if(a==='open'){post=Number(v);asset=0;return navigate('fullscreen');}if(a==='next'||a==='prev'){post=(post+(a==='next'?1:2))%3;asset=0;return render();}if(a==='mute'){muted=!muted;render();notify(muted?'Sunet oprit · prototip':'Sunet pornit · prototip');return;}if(a==='follow'){followed=!followed;render();return;}if(a==='save'){saved=!saved;render();notify(saved?'Salvat în colecția privată · demo':'Eliminat din colecție · demo');return;}if(a==='repost'){reposted=!reposted;render();notify(reposted?'Redistribuire simulată · apasă din nou pentru anulare':'Redistribuire anulată');return;}if(a==='react'){reaction=v;back();return;}if(a==='reply'){replyTo=v;render();root.querySelector('input[name=message]')?.focus();return;}if(a==='cancel-reply'){replyTo='';render();return;}if(a==='comment-like'){el.textContent=el.classList.toggle('selected')?'♥ 13':'♡ 12';return;}if(a==='recipient'){recipients.has(v)?recipients.delete(v):recipients.add(v);render();return;}if(a==='send-internal'){if(!recipients.size)return notify('Alege cel puțin o persoană');notify(`Trimitere simulată către ${recipients.size} conversații`);recipients.clear();back();return;}if(a==='lens'){lens=v;post=0;navigate('feed');return;}if(a==='format'){notify('Format ales: '+v);navigate('feed');return;}if(a==='chat'){selectedPerson=v;navigate('chat');return;}if(a==='creator'){navigate('creator');return;}if(a==='profile-tab'){profileTab=v;render();return;}if(a==='relation-tab'){relationTab=v;render();return;}if(a==='search-tab'){searchTab=v;render();return;}if(a==='favorite'){el.classList.toggle('active');notify(el.classList.contains('active')?'Adăugat la favoriți · demo':'Eliminat din favoriți');return;}if(a==='theme'){document.body.classList.toggle('light');return;}if(a==='toggle'){options[v]=!options[v];render();notify('Preferință schimbată în prototip');return;}if(a==='accept'){selectedPerson='Irina';navigate('chat');notify('Cerere acceptată · simulare');return;}if(a==='decline'){navigate('inbox');notify('Cerere refuzată · simulare');return;}if(a==='story-next'||a==='story-prev'){post=(post+(a==='story-next'?1:2))%3;storyProgress=0;render();return;}if(a==='story-pause'){paused=!paused;render();return;}if(a==='story-like'){el.classList.toggle('active');return;}if(a==='save-draft'){navigate('drafts');notify('Ciornă de proiect păstrată');return;}if(a==='upload-pause'){if(progressTimer){clearInterval(progressTimer);progressTimer=null;el.textContent='Reia';}else render();return;}if(a==='retry'){navigate('feed');notify('Conexiune restabilită · scenariu demo');return;}if(a==='call-toggle'){el.classList.toggle('active');el.setAttribute('aria-pressed',el.classList.contains('active'));return;}if(a==='camera-flip'){notify('Camera spate / selfie · schimbare simulată');return;}if(['camera-mode','publish-type','live-filter','inbox-filter'].includes(a)){el.parentElement.querySelectorAll('button').forEach(b=>b.classList.remove('selected'));el.classList.add('selected');if(a==='inbox-filter')root.querySelector('[data-results]').innerHTML=v==='unread'?rows().split('</button>').slice(0,2).join('</button>')+'</button>':rows();return;}if(a==='login-demo'){navigate('feed');notify('Ai intrat în prototip · fără autentificare reală');return;}if(a==='region')return showDetail('Limbă și regiune','<label class="field">Limbă<select><option>Română</option><option>English</option><option>Polski</option><option>العربية</option></select></label><label class="field">Regiune<select><option>România</option><option>Polonia</option><option>Global</option></select></label>'+button('detail-close','','Păstrează alegerea','primary','Păstrează'));if(a==='audience')return showDetail('Cine poate vedea?', ['Public','Urmăritori','Prieteni apropiați','Doar eu'].map(n=>option('choose:'+n,'people',n)).join(''));if(a==='choose'){root.querySelectorAll('.detail').forEach(n=>n.remove());notify('Ales: '+v+' · prototip');return;}if(a==='duration')return showDetail('Durată Story',['1 oră','24 de ore','7 zile','Până îl retragi'].map(n=>option('choose:'+n,'clock',n)).join(''));if(a==='new-collection')return showDetail('Colecție nouă','<form data-form="collection"><label class="field">Nume<input name="title" required maxlength="40"></label><button class="primary">Creează colecția demo</button></form>');if(a==='edit-tool')return showDetail(v,`<label class="field">${v==='Text'?'Text pe imagine':v==='Sunet'?'Sunet original':'Încadrare'}<input aria-label="${v}" placeholder="${v==='Text'?'Scrie ceva…':'Alegere pentru machetă'}"></label>${button('detail-close','','Aplică în previzualizare','primary','Aplică')}`);if(a==='pay-preview')return showDetail(v,'<p class="quiet" style="padding:15px 0">Flux financiar demonstrativ. Nicio tranzacție nu este creată sau transmisă.</p>'+button('detail-close','','Am înțeles','primary','Închide'));if(a==='recover'||a==='register')return showDetail(a==='recover'?'Recuperare acces':'Creează cont','<p class="quiet" style="padding:15px 0">Ecran de proiectare. Datele reale și walletul sunt gestionate numai de fluxul verificat al aplicației.</p>'+button('detail-close','','Înapoi','primary','Înapoi'));if(a==='blocked')return showDetail('Conturi blocate','<div class="empty"><p>Niciun cont blocat în prototip.</p></div>');if(a==='block')return showDetail('Siguranță',option('choose:Restricționează','profile','Restricționează')+option('choose:Blochează','lock','Blochează')+option('choose:Raportează','flag','Raportează'));if(a==='location')return showDetail('Locație opțională',searchField('Caută un oraș','location')+option('choose:București','pin','București')+option('choose:Kraków','pin','Kraków'));if(a==='voice')return showDetail('Notă vocală','<div class="empty">'+icon('mic')+'<p>Previzualizare înregistrare · microfonul nu este pornit.</p>'+button('choose:Notă vocală simulată','send','Trimite nota demo','primary','Trimite demo')+'</div>');if(a==='attach-file')return showDetail('Fișier',option('choose:Fișier demo atașat','folder','Program.pdf','Document demonstrativ · 128 KB'));if(a==='help')return showDetail('Ajutor',option('choose:Problemă raportată în prototip','flag','Raportează o problemă')+option('go:privacy','lock','Confidențialitate'));});
document.addEventListener('submit',e=>{const f=e.target.closest('[data-form]');if(!f)return;e.preventDefault();const data=new FormData(f);switch(f.dataset.form){case 'comment':{const text=String(data.get('message')||'').trim();if(!text)return;ownComments.push({text,parent:replyTo});replyTo='';render();break;}case 'chat':{const text=String(data.get('message')||'').trim();if(!text)return;messages.push(text);render();root.querySelector('.chat-body')?.scrollTo(0,99999);break;}case 'story':notify('Răspuns simulat în Nexus');f.reset();break;case 'profile':displayName=String(data.get('name')).trim();bio=String(data.get('bio')).trim();navigate('profile');notify('Profil actualizat în prototip');break;case 'publish':draftCaption=String(data.get('caption')||'');progress=38;navigate('progress');break;case 'meeting':messages.push('Întâlnire: '+data.get('title')+' · '+data.get('date')+' '+data.get('time'));navigate('chat');break;case 'collection':root.querySelectorAll('.detail').forEach(n=>n.remove());notify('Colecție demo: '+data.get('title'));break;case 'login':navigate('feed');notify('Sesiune demonstrativă');break;}});
document.addEventListener('input',e=>{if(e.target.dataset.search){const q=e.target.value.toLowerCase();const scope=e.target.closest('.sheet,.body');const results=scope?.querySelector('[data-results]');if(results){if(e.target.dataset.search==='inbox'||e.target.dataset.search==='global'){results.innerHTML=rows(e.target.dataset.search==='global'?'creator':'chat',q)||'<p class="quiet">Niciun rezultat. Încearcă alt nume.</p>';}else results.querySelectorAll('.row,.option').forEach(row=>row.hidden=!row.textContent.toLowerCase().includes(q));}}});
document.addEventListener('keydown',e=>{if(e.key==='Escape'){e.preventDefault();if(root.querySelector('.detail'))root.querySelectorAll('.detail').forEach(n=>n.remove());else back();}if(e.key==='Tab'){const dialog=root.querySelector('.sheet.detail')||root.querySelector('.sheet');if(dialog){const controls=[...dialog.querySelectorAll('button,input,textarea,select,a')].filter(n=>!n.hidden&&n.offsetParent!==null);const first=controls[0],last=controls.at(-1);if(e.shiftKey&&(document.activeElement===first||!dialog.contains(document.activeElement))){e.preventDefault();last?.focus();}else if(!e.shiftKey&&(document.activeElement===last||!dialog.contains(document.activeElement))){e.preventDefault();first?.focus();}}}if(e.target.closest('input,textarea,select'))return;if(route==='fullscreen'&&['ArrowUp','ArrowDown','ArrowLeft','ArrowRight'].includes(e.key)){e.preventDefault();if(e.key==='ArrowUp'||e.key==='ArrowDown'){post=(post+(e.key==='ArrowUp'?1:2))%3;asset=0;}else asset=(asset+(e.key==='ArrowLeft'?1:2))%3;render();}});
let group='';document.getElementById('screen-list').innerHTML=catalogue.map((s,i)=>{let heading=group!==s[1]?`<strong>${esc(s[1]).toUpperCase()}</strong>`:'';group=s[1];return heading+`<a href="#${s[0]}"><span>${String(i+1).padStart(2,'0')}</span>${esc(s[2])}</a>`;}).join('');
document.getElementById('screen-list').addEventListener('click',e=>{const a=e.target.closest('a');if(!a)return;e.preventDefault();document.body.classList.remove('atlas-mode');document.getElementById('atlas').hidden=true;navigate(a.hash.slice(1));});
document.getElementById('theme-toggle').onclick=()=>document.body.classList.toggle('light');
document.getElementById('atlas-toggle').onclick=()=>{const showing=document.body.classList.toggle('atlas-mode');document.getElementById('atlas').hidden=!showing;document.getElementById('atlas-toggle').textContent=showing?'Prototip interactiv':'Toate ecranele';if(showing){clearInterval(storyTimer);clearInterval(progressTimer);document.getElementById('atlas').innerHTML=catalogue.map((s,i)=>`<article class="atlas-card"><button data-open-screen="${s[0]}">${String(i+1).padStart(2,'0')} · ${esc(s[2])} ↗</button><div class="atlas-window"><div class="prototype">${renderScreen(s[0])}</div></div></article>`).join('');}else render();};
document.getElementById('atlas').addEventListener('click',e=>{const b=e.target.closest('[data-open-screen]');if(!b)return;document.getElementById('atlas-toggle').click();navigate(b.dataset.openScreen);window.scrollTo(0,0);});
window.addEventListener('popstate',()=>{route=titles[location.hash.slice(1)]?location.hash.slice(1):'feed';render();});
window.addEventListener('hashchange',()=>{const next=location.hash.slice(1);if(titles[next]&&route!==next){route=next;render();}});
route=titles[location.hash.slice(1)]?location.hash.slice(1):'feed';history.replaceState({nexusDesign:true,nexusDesignDepth:0},'',location.href);render();
